// src/pages/LoginPage.jsx
import React from "react";
import { useState, useEffect } from "react";
import LoginForm from "../components/LoginForm";
import CompanyLogo from "../components/CompanyLogo";
import axios from "axios";
import { Briefcase } from "lucide-react";
import backgroundImg from "../images/loginBackground.jpg"
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import 'bootstrap-icons/font/bootstrap-icons.css';
import "../css/LoginPage.css"
import InputField from "../components/InputFields";
import { Navigate } from "react-router-dom";
import { Link } from "react-router-dom";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const Forgot = () => {
    const handleLogin = async (employeeId, password) => {
        const response = await axios.post(
            "/WebApplication/auth/login",
            {
                employeeId,
                password,
            },
            {
                withCredentials: true, // 🚨 This ensures browser stores cookie
            }
        );
        console.log("Login success:", response.data);
        // Redirect to dashboard
        window.location.replace("/WebApplication/dashboard");
    };

      const images = [
        BASE_URL + "/WebApplication/images/slide.jpeg",
        BASE_URL + "/WebApplication/images/slide2.jpeg",
        BASE_URL + "/WebApplication/images/slide3.jpg",
        BASE_URL + "/WebApplication/images/slide4.jpg",
        BASE_URL + "/WebApplication/images/slide5.jpg",
        BASE_URL + "/WebApplication/images/slide6.jpg",
        BASE_URL + "/WebApplication/images/slide8.jpeg",
        BASE_URL + "/WebApplication/images/slide9.jpeg",
        BASE_URL + "/WebApplication/images/slide10.jpg",
      ];
    
      const [currentImage, setCurrentImage] = useState(0);
    
      useEffect(() => {
        const interval = setInterval(() => {
          setCurrentImage((prev) => (prev + 1) % images.length);
        }, 4000);
    
        return () => clearInterval(interval);
      }, []);

    return (

        <div class="container-fluid login-container">
            <div class="row vh-100">
                <div
                    className="col-lg-6 d-none d-lg-flex branding-section"
                    style={{
                        backgroundImage: `url(${images[currentImage]})`,
                        backgroundSize: "cover",
                        backgroundPosition: "center",
                        transition: "background-image 1s ease-in-out"
                    }}
                >
                    <div class="overlay"></div>
                    <div class="branding-content text-white">
                        <img
                            src={BASE_URL + "/WebApplication/images/woco.png"}
                            alt="Begapt Solutions"
                            className="img-fluid logo-shadow"
                            style={{ height: "120px" }}
                        />
                        <div className="text-center align-items-center m-5">
                            <h2 className="text-light">Woco Tech Elastomere Noida Ltd.</h2>
                            <h3 className="text-light">Woco Group</h3>

                        </div>
                    </div>

                </div>
                {/* <!-- Right Side - Login Form --> */}
                <div class="col-lg-6 d-flex align-items-center justify-content-center bg-light">

                    <div class="login-card shadow">

                        <div class="text-center mb-4">
                            <img
                                src={BASE_URL + "/WebApplication/images/woco.jpg"}
                                alt="Begapt Solutions"
                                className="img-fluid"
                                style={{ height: "60px" }}
                            />
                            <h4 className="mt-3">Forgot Your Password?</h4>
                            <p class="text-muted small">
                                Enter your registered email to receive a reset link.
                            </p>
                        </div>

                        <form>
                            <div class="mb-3">
                                {/* <label class="form-label">Email Address</label> */}
                                {/* <input type="email" class="form-control" placeholder="Enter your email" required> */}
                                <InputField
                                    type="text"
                                    label="Registered Email"
                                    placeholder="emailaddress@gmail.com"
                                />
                            </div>

                            <div class="d-flex justify-content-end mb-3">
                                <Link to="/WebApplication/loginpage" class="forgot-link">
                                    ← Back to Login
                                </Link>
                            </div>

                            <button type="submit" class="btn btn-woco w-100">
                                Send Reset Link
                            </button>
                        </form>

                        <div class="text-center mt-4">
                            <small>© 2026 Woco Group</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Forgot;
