import React from "react";
import { Eye, EyeOff, Upload, User, Lock, Mail } from "lucide-react";

const InputField = ({
  type = "text",
  label,
  name,
  value,
  onChange,
  placeholder,
  error,
  options = [],
  checked,
  multiple = false,
  showToggle = false,
  showPassword,
  setShowPassword,
  rows = 3,
}) => {
  // Decide icon based on type
  const getIcon = () => {
    switch (type) {
      case "text":
        return <User size={18} />;
      case "email":
        return <Mail size={18} />;
      case "password":
        return <Lock size={18} />;
      default:
        return null;
    }
  };

  switch (type) {
    case "textarea":
      return (
        <div className="mb-3">
          {label && <label className="form-label">{label}</label>}
          <textarea
            className={`form-control ${error ? "is-invalid" : ""}`}
            name={name}
            rows={rows}
            placeholder={placeholder}
            value={value}
            onChange={onChange}
          />
          {error && <div className="invalid-feedback">{error}</div>}
        </div>
      );

    case "select":
      return (
        <div className="mb-3">
          {label && <label className="form-label">{label}</label>}
          <select
            className={`form-select ${error ? "is-invalid" : ""}`}
            name={name}
            value={value}
            onChange={onChange}
          >
            <option value="">-- Select --</option>
            {options.map((opt, i) => (
              <option key={i} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
          {error && <div className="invalid-feedback">{error}</div>}
        </div>
      );

    case "checkbox":
    case "radio":
      return (
        <div className="mb-3 form-check">
          <input
            type={type}
            className={`form-check-input ${error ? "is-invalid" : ""}`}
            id={name}
            name={name}
            checked={checked}
            value={value}
            onChange={onChange}
          />
          <label className="form-check-label" htmlFor={name}>
            {label}
          </label>
          {error && <div className="invalid-feedback d-block">{error}</div>}
        </div>
      );

    case "file":
      return (
        <div className="mb-3">
          {label && <label className="form-label">{label}</label>}
          <div className="input-group">
            <span className="input-group-text">
              <Upload size={16} />
            </span>
            <input
              type="file"
              className={`form-control ${error ? "is-invalid" : ""}`}
              name={name}
              onChange={onChange}
              multiple={multiple}
            />
          </div>
          {error && <div className="invalid-feedback d-block">{error}</div>}
        </div>
      );

    case "password":
      return (
        <div className="mb-3">
          {label && <label className="form-label">{label}</label>}
          <div className="input-group">
            <span className="input-group-text">{getIcon()}</span>
            <input
              type={showPassword ? "text" : "password"}
              className={`form-control ${error ? "is-invalid" : ""}`}
              name={name}
              value={value}
              onChange={onChange}
              placeholder={placeholder}
            />
            {showToggle && (
              <span
                className="input-group-text"
                style={{ cursor: "pointer" }}
                onClick={() => setShowPassword(!showPassword)}
              >
                {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
              </span>
            )}
          </div>
          {error && <div className="invalid-feedback">{error}</div>}
        </div>
      );

    default: // text, email, number, date, etc.
      return (
        <div className="mb-3">
          {label && <label className="form-label">{label}</label>}
          <div className="input-group">
            {getIcon() && <span className="input-group-text">{getIcon()}</span>}
            <input
              type={type}
              className={`form-control ${error ? "is-invalid" : ""}`}
              name={name}
              value={value}
              onChange={onChange}
              placeholder={placeholder}
            />
          </div>
          {error && <div className="invalid-feedback">{error}</div>}
        </div>
      );
  }
};

export default InputField;